package com.example.simpleaccountant.ui.transactions;
import android.app.AlertDialog;import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.TransactionDao;
public class TransactionListActivity extends AppCompatActivity {private TransactionDao dao;private TransactionAdapter adapter;private TextView empty;
@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_list);dao=new TransactionDao(this);empty=findViewById(R.id.tvEmpty);RecyclerView rv=findViewById(R.id.recyclerView);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new TransactionAdapter(t->new AlertDialog.Builder(this).setMessage("Delete?").setPositiveButton("Yes",(d,w)->{dao.deleteTransaction(t.getId());load();}).setNegativeButton("No",null).show());rv.setAdapter(adapter);findViewById(R.id.fabAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));}
@Override protected void onResume(){super.onResume();load();} private void load(){adapter.setItems(dao.getAllTransactions());empty.setText(adapter.getItemCount()==0?"No transactions yet":"");}}
